                                        showSnackbar("Aviso: não salvou perfil (${e.message})")
                                        startActivity(Intent(this@ActivityCriar2, ActivityHomeMaker::class.java).apply {
                                            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
